	if cfg.Table != "" {
		if terr := recordstore.CheckTableRef(cfg.Table); terr != nil {
			panic("RunStore: " + terr.Error())
		}
	}
	if cfg.ReadTable != "" {
		if terr := recordstore.CheckTableRef(cfg.ReadTable); terr != nil {
			panic("RunStore: ReadTable: " + terr.Error())
		}
	}
	if alloc == nil {
		alloc = memory.NewGoAllocator()
	}
	inst = &RunStore{exec: exec, alloc: alloc, cfg: cfg, dml: lowlevel.NewInEntityAgentrunTable(alloc, 64), dirty: make(map[string]struct{}), stampers: cfg.Stampers}
