// ScanRun iterates the entities whose rows carry a conforming Run
// component, ordered by (Order, Key) — so entities sharing an Order
// still come out in a fixed sequence. Rows that tie on BOTH (the same
// key written twice at the same Order) are not ordered against each
// other by this clause; the table keeps newest-per-key, so which of
// them survives is the engine's choice, not the scan's.
// opts.KeyPrefix restricts the scan to keys starting with it — a
// primary-key range read, since the table sorts by (key, order).
// opts.ExtraPredicate (trusted raw SQL over the physical columns —
// never untrusted input) further restricts the scan; opts.Limit
// caps the row count. The Filter artefact uses ClickHouse
// built-ins only, so this is a single SELECT — no helper UDFs, no
// multi-statement script (the ExecutorI contract). The sequence is
// single-use; ctx must stay valid until iteration completes; an
// error ends it as a final (nil, err) pair. Scans see only flushed
// rows.
func (inst *RunStore) ScanRun(ctx context.Context, opts recordstore.ScanOpts) iter.Seq2[*RunEntity, error] {
	where := agentrunScanRunFilter
	if opts.KeyPrefix != "" {
		where = "(" + where + ") AND " + agentrunKeyPrefixPredicate(opts.KeyPrefix)
	}
	if opts.ExtraPredicate != "" {
		where = "(" + where + ") AND (" + opts.ExtraPredicate + ")"
	}
	sql := "SELECT * FROM " + inst.readTable() +
		" WHERE " + where +
		" ORDER BY " + RunColOrder + " ASC, " + RunColKey + " ASC"
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += agentrunArrowOutputSettings
	return inst.iterateEntities(ctx, sql)
}

// Latest returns the newest row for key, tombstone-blind (the raw
// row-level primitive — a deleted key still returns its tombstone
// row; GetLive is the interpreted state-view read). Reads see only
// flushed rows.
func (inst *RunStore) Latest(ctx context.Context, key string) (ent *RunEntity, found bool, err error) {
	sql := "SELECT * FROM " + inst.readTable() +
		" WHERE " + RunColKey + " = " + agentrunKeyLiteral(key) +
		" ORDER BY " + RunColOrder + " DESC LIMIT 1" + agentrunArrowOutputSettings
	ents, err := inst.queryEntities(ctx, sql)
	if err != nil || len(ents) == 0 {
		return
	}
	ent = ents[0]
	found = true
	return
}

// Replay iterates the rows for key with the order column >= fromOrder
// in ascending order — the event-replay primitive. A zero fromOrder
// replays everything (zero time.Time has no defined UnixNano;
// recordstore.SeqTs(0) is the equivalent explicit bound);
// opts.To bounds the replay exclusively ("state as of To") and
// opts.Limit caps the row count. The sequence is single-use; ctx
// must stay valid until iteration completes; the query may execute
// at call time or lazily during iteration (buffered in v1 — a
// streaming executor changes nothing visible); an error ends the
// sequence as a final (nil, err) pair. Reads see only flushed rows.
func (inst *RunStore) Replay(ctx context.Context, key string, fromOrder time.Time, opts recordstore.ReplayOpts) iter.Seq2[*RunEntity, error] {
	sql := "SELECT * FROM " + inst.readTable() +
		" WHERE " + RunColKey + " = " + agentrunKeyLiteral(key)
	if !fromOrder.IsZero() {
		sql += " AND " + RunColOrder + " >= fromUnixTimestamp64Nano(" + strconv.FormatInt(fromOrder.UnixNano(), 10) + ")"
	}
	if !opts.To.IsZero() {
		sql += " AND " + RunColOrder + " < fromUnixTimestamp64Nano(" + strconv.FormatInt(opts.To.UnixNano(), 10) + ")"
	}
	sql += " ORDER BY " + RunColOrder + " ASC"
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += agentrunArrowOutputSettings
	return inst.iterateEntities(ctx, sql)
}

// --- state view (Delete / GetLive; ADR-0100 SD4). Versioned writes
// go through Begin — appending a new version IS the update. ---

// Delete appends a tombstone row for id — the marker row the tombstone
// pair recognises. Under the default pair the row carries no components
// and the u8 Lifecycle column marks the deletion; a configured pair
// composes the marker through TombstoneWrite on an ordinary builder
// frame instead (whose Lifecycle column then reads LifecycleLive — the
// pair is the marker). Either way the deletion writes through to
// attached cache views like any commit — versioned, so GetLive reads
// the key as absent immediately.
func (inst *RunStore) Delete(id string, ts time.Time) (err error) {
	return inst.DeleteCtx(context.Background(), id, ts)
}

// DeleteCtx is Delete with the context BeginCtx hands the configured
// stampers (ADR-0295 §SD7).
func (inst *RunStore) DeleteCtx(ctx context.Context, id string, ts time.Time) (err error) {
	if inst.cfg.TombstoneWrite != nil {
		b := inst.BeginCtx(ctx, id, ts)
		b.tombstone = true
		inst.cfg.TombstoneWrite(b)
		return b.Commit()
	}
	lowlevel.InEntityAgentrunTableBeginEntity(inst.dml)
	lowlevel.InEntityAgentrunTableSetId(inst.dml, id)
	lowlevel.InEntityAgentrunTableSetTimestamp(inst.dml, ts)
	lowlevel.InEntityAgentrunTableSetLifecycle(inst.dml, recordstore.LifecycleTombstone)
	// The marker row has no attribute to carry a stamp, but the stampers
	// are consulted all the same: one that refuses (an actor stamper with
	// no principal on ctx) refuses the deletion too (ADR-0295 §SD8).
	pushed := inst.applyStampers(ctx)
	err = lowlevel.InEntityAgentrunTableCommitEntity(inst.dml)
	inst.dml.PopMembershipsHighCardRef(pushed)
	if err != nil {
		_ = lowlevel.InEntityAgentrunTableRollbackEntity(inst.dml) // discard the failed frame; the store stays usable
		return
	}
	inst.buffered++
	inst.dirty[id] = struct{}{}
	inst.notifyWrite(id, &RunEntity{ID: id, Ts: ts, Lifecycle: recordstore.LifecycleTombstone})
	ci, _ := callident.CallIdentityFrom(ctx)
	inst.noteCommitted(recordstore.WrittenKey[string, time.Time]{Key: id, Order: ts, Lifecycle: recordstore.LifecycleTombstone, Tombstone: true, Identity: ci})
	return
}

// GetLive is Latest plus tombstone interpretation: newest row wins, a
// tombstone reads as absent — the state-view read (the cache view
// carries the cached twin). Interpretation runs Go-side through the
// tombstone pair's detect, on the one newest row this verb needs.
func (inst *RunStore) GetLive(ctx context.Context, key string) (ent *RunEntity, found bool, err error) {
	ent, found, err = inst.Latest(ctx, key)
	if err != nil || !found {
		return
	}
	if inst.isTombstone(ent) {
		ent = nil
		found = false
	}
	return
}

// ScanLiveRun is the state view's scan: the newest row of every key,
// kept when that row carries a conforming Run component and is not a
// tombstone — what GetLive would answer for each key, in one query.
// The collapse to the newest row runs over all of a key's rows BEFORE
// the component test: a key whose newest row is a tombstone, or carries
// only other components, is absent, never represented by an older row
// it superseded.
// opts.KeyPrefix restricts the scan to keys starting with it — a
// primary-key range read, since the table sorts by (key, order).
// opts.ExtraPredicate (trusted raw SQL over the physical columns)
// applies to the collapsed rows, so it narrows the live set and cannot
// uncover a superseded row. Entities come out ordered by key.
// opts.Limit caps the rows the query returns before the Go-side
// tombstone test, so under a configured tombstone pair whose marker
// satisfies the Filter a limited scan can yield fewer than Limit.
// Reads see only flushed rows; the sequence is single-use, and an
// error ends it as a final (nil, err) pair.
func (inst *RunStore) ScanLiveRun(ctx context.Context, opts recordstore.ScanOpts) iter.Seq2[*RunEntity, error] {
	inner := "SELECT * FROM " + inst.readTable()
	if opts.KeyPrefix != "" {
		inner += " WHERE " + agentrunKeyPrefixPredicate(opts.KeyPrefix)
	}
	inner += " ORDER BY " + RunColOrder + " DESC LIMIT 1 BY " + RunColKey
	where := "(" + agentrunScanRunFilter + ")"
	if opts.ExtraPredicate != "" {
		where += " AND (" + opts.ExtraPredicate + ")"
	}
	sql := "SELECT * FROM (" + inner + ") WHERE " + where + " ORDER BY " + RunColKey + " ASC"
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += agentrunArrowOutputSettings
	return func(yield func(*RunEntity, error) bool) {
		for ent, err := range inst.iterateEntities(ctx, sql) {
			if err != nil {
				yield(nil, err)
				return
			}
			if inst.isTombstone(ent) {
				continue
			}
			if !yield(ent, nil) {
				return
			}
		}
	}
}

// UpdateIf is the compare-and-set on key's row (ADR-0223 §SD3): one
// lightweight update, guarded by where on the row's current values, that
// applies sets. It does not report whether it won — the caller reads the
// row back and decides, since the read-back is the answer. where is SQL
// over the physical columns, trusted input only (the <Kind>Guard<Field>
// helpers render it); an empty one is refused, since an unguarded update
// is not a compare-and-set. A key with buffered, unflushed rows is
// refused too: the update sees only flushed rows. Attached cache views
// drop the key, so the next read refetches what the update left.
//
// The table lives under rowcas's conditions: the sequential update mode
// on every statement, the block-position settings (EnsureTable applies
// them), no heavyweight mutation ever, an immutable key, no async_insert
// on the claim path, and one server (ADR-0319 §SD1).
func (inst *RunStore) UpdateIf(ctx context.Context, key string, where string, sets ...rowcas.Set) (err error) {
	if strings.TrimSpace(where) == "" {
		return eh.Errorf("compare-and-set without a guard")
	}
	if len(sets) == 0 {
		return eh.Errorf("compare-and-set with nothing to set")
	}
	if _, d := inst.dirty[key]; d {
		return eh.Errorf("compare-and-set on a key with buffered rows; Flush first")
	}
	sql := rowcas.UpdateSQL(inst.writeTable(), sets, RunColKey+" = "+agentrunKeyLiteral(key)+" AND ("+where+")")
	err = inst.exec.Exec(ctx, sql)
	inst.notifyWrite(key, nil)
	if err != nil {
		err = eh.Errorf("compare-and-set on %s: %w", inst.writeTable(), err)
	}
	return
}

