// --- decode (Arrow → entity bags). ---

// agentrunSectionReaderI is the uniform slice of the generated read-access
// readers. Column indices stay at their constructor defaults — the
// schema order a SELECT * returns.
type agentrunSectionReaderI interface {
	LoadFromRecord(raruntime.RecordI) error
	Release()
}

func (inst *RunStore) queryEntities(ctx context.Context, sql string) (ents []*RunEntity, err error) {
	for rec, rerr := range inst.exec.QueryArrow(ctx, sql) {
		if rerr != nil {
			err = eh.Errorf("query entities: %w", rerr)
			return
		}
		batch, derr := decodeRunRecord(rec)
		rec.Release()
		if derr != nil {
			err = derr
			return
		}
		ents = append(ents, batch...)
	}
	return
}

// iterateEntities adapts the buffered query path to the single-use
// iterator contract shared by Replay and the Scan verbs: entities
// yield in query order; an error yields once as (nil, err) and ends
// the sequence.
func (inst *RunStore) iterateEntities(ctx context.Context, sql string) iter.Seq2[*RunEntity, error] {
	return func(yield func(*RunEntity, error) bool) {
		ents, err := inst.queryEntities(ctx, sql)
		if err != nil {
			yield(nil, err)
			return
		}
		for _, ent := range ents {
			if !yield(ent, nil) {
				return
			}
		}
	}
}

// decodeRunRecord reads one fetched Arrow record into entity bags:
// envelope from the plain readers, components via presence-gated,
// membership-matched reads (fat rows carry optional components — the
// kind-homogeneous helpers cannot decode them).
func decodeRunRecord(rec arrow.RecordBatch) (ents []*RunEntity, err error) {
	idR := lowlevel.NewReadAccessAgentrunTablePlainEntityIdAttributes()
	tsR := lowlevel.NewReadAccessAgentrunTablePlainEntityTimestampAttributes()
	lcR := lowlevel.NewReadAccessAgentrunTablePlainEntityLifecycleAttributes()
	runCellR := lowlevel.NewReadAccessAgentrunTableTaggedRunCell()
	runConversationR := lowlevel.NewReadAccessAgentrunTableTaggedRunConversation()
	runOwnerAppR := lowlevel.NewReadAccessAgentrunTableTaggedRunOwnerApp()
	runCoordinatorR := lowlevel.NewReadAccessAgentrunTableTaggedRunCoordinator()
	runStateR := lowlevel.NewReadAccessAgentrunTableTaggedRunState()
	runFingerprintR := lowlevel.NewReadAccessAgentrunTableTaggedRunFingerprint()
	runBuildR := lowlevel.NewReadAccessAgentrunTableTaggedRunBuild()
	runProfileR := lowlevel.NewReadAccessAgentrunTableTaggedRunProfile()
	runSettingsR := lowlevel.NewReadAccessAgentrunTableTaggedRunSettings()
	runLabelLevelR := lowlevel.NewReadAccessAgentrunTableTaggedRunLabelLevel()
	runLabelTierR := lowlevel.NewReadAccessAgentrunTableTaggedRunLabelTier()
	runLabelExposureR := lowlevel.NewReadAccessAgentrunTableTaggedRunLabelExposure()
	runLabelOriginR := lowlevel.NewReadAccessAgentrunTableTaggedRunLabelOrigin()
	runCreatedR := lowlevel.NewReadAccessAgentrunTableTaggedRunCreated()
	runLastOrdinalR := lowlevel.NewReadAccessAgentrunTableTaggedRunLastOrdinal()
	runClosedR := lowlevel.NewReadAccessAgentrunTableTaggedRunClosed()
	runDigestR := lowlevel.NewReadAccessAgentrunTableTaggedRunDigest()
	runHeadR := lowlevel.NewReadAccessAgentrunTableTaggedRunHead()
	runVersionR := lowlevel.NewReadAccessAgentrunTableTaggedRunVersion()
	runDeletedByR := lowlevel.NewReadAccessAgentrunTableTaggedRunDeletedBy()
	runDeletedAtR := lowlevel.NewReadAccessAgentrunTableTaggedRunDeletedAt()
	readers := []agentrunSectionReaderI{idR, tsR, lcR, runCellR, runConversationR, runOwnerAppR, runCoordinatorR, runStateR, runFingerprintR, runBuildR, runProfileR, runSettingsR, runLabelLevelR, runLabelTierR, runLabelExposureR, runLabelOriginR, runCreatedR, runLastOrdinalR, runClosedR, runDigestR, runHeadR, runVersionR, runDeletedByR, runDeletedAtR}
	for _, r := range readers {
		err = r.LoadFromRecord(rec)
		if err != nil {
			err = eh.Errorf("load agentrun reader from record: %w", err)
			return
		}
	}
	defer func() {
		for _, r := range readers {
			r.Release()
		}
	}()

	n := idR.ValueId.Len()
	tsType, ok := tsR.ValueTs.DataType().(*arrow.TimestampType)
	if !ok {
		err = eh.Errorf("order column is not a timestamp (got %s)", tsR.ValueTs.DataType())
		return
	}
	ents = make([]*RunEntity, 0, n)
	for i := range n {
		ent := &RunEntity{
			ID:        idR.ValueId.Value(i),
			Ts:        tsR.ValueTs.Value(i).ToTime(tsType.Unit).UTC(),
			Lifecycle: lcR.ValueLifecycle.Value(i),
		}
		{
			row, ok, e := runReadRow(i, runCellR.GetAttributes(), runCellR.GetMemberships(), runConversationR.GetAttributes(), runConversationR.GetMemberships(), runOwnerAppR.GetAttributes(), runOwnerAppR.GetMemberships(), runCoordinatorR.GetAttributes(), runCoordinatorR.GetMemberships(), runStateR.GetAttributes(), runStateR.GetMemberships(), runFingerprintR.GetAttributes(), runFingerprintR.GetMemberships(), runBuildR.GetAttributes(), runBuildR.GetMemberships(), runProfileR.GetAttributes(), runProfileR.GetMemberships(), runSettingsR.GetAttributes(), runSettingsR.GetMemberships(), runLabelLevelR.GetAttributes(), runLabelLevelR.GetMemberships(), runLabelTierR.GetAttributes(), runLabelTierR.GetMemberships(), runLabelExposureR.GetAttributes(), runLabelExposureR.GetMemberships(), runLabelOriginR.GetAttributes(), runLabelOriginR.GetMemberships(), runCreatedR.GetAttributes(), runCreatedR.GetMemberships(), runLastOrdinalR.GetAttributes(), runLastOrdinalR.GetMemberships(), runClosedR.GetAttributes(), runClosedR.GetMemberships(), runDigestR.GetAttributes(), runDigestR.GetMemberships(), runHeadR.GetAttributes(), runHeadR.GetMemberships(), runVersionR.GetAttributes(), runVersionR.GetMemberships(), runDeletedByR.GetAttributes(), runDeletedByR.GetMemberships(), runDeletedAtR.GetAttributes(), runDeletedAtR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read run component: %w", e)
				return
			}
			if ok {
				row.ID = ent.ID
				ent.Run = option.Some(row)
			}
		}
		ents = append(ents, ent)
	}
	return
}
